mapper.select:
SELECT  
WHERE p.parent_id IS NULL AND p.scope = #{scope}
AND p.exchange = #{exchange} AND p.market = #{market} AND p.symbol = #{symbol}
AND (LOWER(p.title) LIKE #{query} OR LOWER(p.body) LIKE #{query} OR LOWER() LIKE #{query})
ORDER BY like_count DESC, p.id DESC
LIMIT 21 OFFSET #{offset}
